window.ARTICLES_DATA = [{"id": "tighter-regulation-not-enough-to-stop-importing--2a7007", "cat": "precious", "date": "2026-11-15", "title": "قوانین سختگیرانه‌اماراتی نتوانست واردات طلاهای غیرقانونی را متوقف کند", "lede": "گزارشی جدید نشان می‌دهد که با وجود مقررات جدید ۲۰۲۳، امارات متحده عربی هنوز قادر به ردیابی کامل واردات طلاهای غیرقانونی نیست.", "tags": ["امارات", "طلا", "واردات غیرقانونی", "قوانین 2023", "زنجیره تأمین"], "facts": [["2023", "اجرای مقررات جدید برای ردیابی منبع طلا"], ["گزارش MINING.COM", "نشان می‌دهد ردیابی واردات طلا بهبود نیافته است"], ["امارات", "به عنوان بزرگ‌ترین واردکننده طلا در خاورمیانه شناخته می‌شود"], ["واردات طلا", "بخش عمده‌ای از این واردات به‌صورت غیرقانونی گزارش شده‌اند"]], "body": [{"t": "p", "x": "امارات متحده عربی، که به‌عنوان یکی از بزرگ‌ترین مراکز تجاری طلا در خاورمیانه شناخته می‌شود، در سال ۲۰۲۳ مقررات جدیدی برای تقویت ردیابی منبع طلاها تصویب کرد. این قوانین جدید شامل الزام ارائه گواهی‌های منبع معتبر برای تمام واردات طلا به کشور می‌شد."}, {"t": "p", "x": "با این حال، گزارشی منتشر شده توسط MINING.COM نشان می‌دهد که اجرای این مقررات تاکنون نتوانسته است شفافیت لازم را در زنجیره تأمین طلا ایجاد کند. بر اساس داده‌های موجود، مقامات اماراتی هنوز قادر به شناسایی دقیق تمام بارهای طلا وارداتی نیستند."}, {"t": "p", "x": "گزارش به‌طور خاص به این نکته اشاره دارد که حتی پس از اعمال قوانین جدید، حجم قابل‌توجهی از طلاهای وارداتی به امارات به‌صورت غیرقانونی یا بدون اسناد معتبر وارد می‌شوند. این وضعیت نگرانی‌های بین‌المللی درباره استفاده از طلاهای استخراج‌شده در مناطق تحت تحریم یا با نقض حقوق بشر را تشدید می‌کند."}, {"t": "p", "x": "«قوانین جدید گامی مهم بود، اما به تنهایی کافی نیست»، یک مقام رسمی در وزارت تجارت امارات در مصاحبه‌ای با MINING.COM گفت. او افزود که نیاز به همکاری بیشتر با نهادهای بین‌المللی و بهبود سامانه‌های دیجیتال ردیابی وجود دارد."}, {"t": "p", "x": "از منظر بازار، عدم توانایی در ردیابی طلاهای غیرقانونی می‌تواند به کاهش اعتماد سرمایه‌گذاران و خریداران نهایی منجر شود. شرکت‌های جواهری که به‌دنبال تأمین طلاهای با منبع شفاف هستند، ممکن است به‌جای امارات، به بازارهای دیگر روی آورند."}, {"t": "p", "x": "علاوه بر این، این مشکل می‌تواند فشارهای قانونی بیشتری بر روی بانک‌ها و مؤسسات مالی واردکننده طلا وارد کند، چرا که قوانین ضدپولشویی (AML) به‌صورت فزاینده‌ای به شفافیت زنجیره تأمین طلا نیاز دارند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "تحلیل‌گران بر این باورند که برای رفع این خلأ، امارات باید نه تنها قوانین داخلی را تقویت کند، بلکه با سازمان‌های بین‌المللی مانند شورای جهانی طلا (World Gold Council) و شبکه‌های ردیابی بلاک‌چین همکاری نزدیک‌تری برقرار نماید. تنها در این صورت می‌توان اطمینان حاصل کرد که طلاهای وارداتی به این کشور از منابع قانونی و شفاف می‌آیند و نقش امارات در بازار جهانی طلا به‌عنوان یک مرکز تجاری معتبر حفظ می‌شود."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/tighter-regulation-not-enough-to-stop-importing-illicit-gold-to-uae-report/", "orig": "Tighter regulation not enough to stop importing illicit gold to UAE: report"}}, {"id": "nvidia-turmoil-tests-metals-demand-boom-614cc2", "cat": "copper", "date": "2026-11-15", "title": "ترک جنسن هوانگ از Nvidia؛ تهدیدی برای رونق تقاضای فلزات", "lede": "جدایی بنیان‌گذار Nvidia از رهبری شرکت، نگرانی‌ها را دربارهٔ رشد تقاضای فلزات توسط مراکز داده هوش مصنوعی تشدید می‌کند.", "tags": ["Nvidia", "هوش مصنوعی", "تقاضای فلزات", "مراکز داده", "استخراج‌کنندگان"], "facts": [["Jensen Huang", "بنیان‌گذار و مدیرعامل Nvidia از شرکت جدا شد"], ["رهبری AI", "خروج هوانگ باعث تردید سرمایه‌گذاران در توانایی Nvidia برای حفظ رهبری در حوزه هوش مصنوعی شد"], ["وابستگی معدن‌کاران", "بسیاری از شرکت‌های استخراجی به رشد تقاضای مس و سایر فلزات توسط مراکز داده جدید وابسته‌اند"], ["تقاضای فلزات", "روند رشد تقاضای فلزات به‌ویژه مس، نیکل و گرافیت توسط پروژه‌های AI به‌عنوان یک بوم‌ساز اقتصادی شناخته می‌شود"]], "body": [{"t": "p", "x": "شرکت Nvidia، پیشرو در زمینه پردازشگرهای گرافیکی برای هوش مصنوعی، با اعلام جدایی جنسن هوانگ، بنیان‌گذار و مدیرعامل خود، موجی از نگرانی‌ها را در میان سرمایه‌گذاران و صنعت‌گران ایجاد کرده است. این تغییر رهبری در زمانی رخ می‌دهد که تقاضای جهانی برای فلزات مورد استفاده در مراکز داده هوش مصنوعی به‌صورت چشمگیری در حال افزایش است."}, {"t": "p", "x": "دستگاه‌های پردازشی پیشرفته Nvidia، به‌عنوان ستون فقرات زیرساخت‌های هوش مصنوعی، به‌منظور پشتیبانی از مدل‌های بزرگ زبانی و پردازش‌های محاسباتی سنگین، به مقادیر عظیمی از مس، نیکل، گرافیت و سایر فلزات صنعتی نیاز دارند. رشد سریع مراکز داده برای این کاربردها، پیش‌بینی می‌شود که تقاضای این مواد را در سال‌های آینده چند برابر کند."}, {"t": "p", "x": "با خروج هوانگ، تحلیل‌گران بازار به این نکته اشاره می‌کنند که عدم قطعیت در رهبری Nvidia می‌تواند به کاهش سرعت سرمایه‌گذاری در پروژه‌های جدید AI منجر شود. این مسأله به‌ویژه برای شرکت‌های معدنی که به‌صورت مستقیم به تقاضای این فلزات وابسته‌اند، ریسک قابل‌توجهی محسوب می‌شود."}, {"t": "p", "x": "به گفتهٔ کارشناسان، شرکت‌های استخراجی بزرگ مانند Freeport-McMoRan و Glencore که بخش قابل‌توجهی از تولید مس و نیکل خود را به مشتریان حوزه فناوری اختصاص داده‌اند، ممکن است با کاهش سفارشات مواجه شوند. این وضعیت می‌تواند فشار بر حاشیه سود و برنامه‌های گسترش سرمایه‌ای این شرکت‌ها وارد کند."}, {"t": "p", "x": "در همین حال، برخی از سرمایه‌گذاران به دنبال تنوع‌بخشی به سبدهای خود هستند و به جای تمرکز بر فلزات مرتبط با AI، به فلزات گرانبها و باتری‌محور مانند لیتیوم و کبالت می‌نگرند. این تغییر جهت می‌تواند الگوی جدیدی در تقاضای مواد معدنی ایجاد کند و بازارهای سنتی فلزات صنعتی را تحت تأثیر قرار دهد."}, {"t": "p", "x": "به‌علاوه، نوسانات قیمت سهام Nvidia پس از اعلام خبر خروج هوانگ، نشانگر حساسیت بازار به هر گونه تغییر در رهبری شرکت‌های کلیدی فناوری است. این نوسانات می‌تواند به‌صورت غیرمستقیم بر تصمیم‌گیری‌های سرمایه‌گذاری در پروژه‌های زیرساختی و استخراجی تأثیر بگذارد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه خروج جنسن هوانگ می‌تواند موقتاً باعث کاهش سرعت رشد تقاضای فلزات توسط مراکز داده AI شود، اما روند بلندمدت نیاز به این مواد به‌دلیل گسترش مداوم هوش مصنوعی و اینترنت اشیاء همچنان مثبت باقی می‌ماند. استخراج‌کنندگان باید استراتژی‌های خود را برای مواجهه با نوسانات تقاضا بازنگری کنند و به تنوع‌بخشی به بازارهای هدف، به‌ویژه فلزات باتری‌محور، بپردازند تا ریسک‌های ناشی از تغییرات رهبری در شرکت‌های فناوری را کاهش دهند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/nvidia-turmoil-tests-metals-demand-boom/", "orig": "Nvidia turmoil tests metals demand boom"}}, {"id": "tiny-animals-found-living-inside-deep-sea-nodule-cb188d", "cat": "geo", "date": "2026-11-15", "title": "حیوانات ریز درون نودل‌های عمیق‌دریایی کشف شد؛ ایالات متحده مجوز تجاری نخستین استخراج را بررسی می‌کند", "lede": "پژوهشگران موجودات مینیاتوری را در نودل‌های پلی‌متالیک در عمق ۵٬۰۰۰ متر اقیانوس شناسایی کردند؛ در همین حال دولت آمریکا اولین درخواست مجوز استخراج تجاری را ارزیابی می‌کند.", "tags": ["نودل‌های عمیق‌دریایی", "استخراج دریا", "حیات میکرو", "مجوز تجاری", "فلزات باتری"], "facts": [["عمق کشف", "۵٬۰۰۰ تا ۶٬۰۰۰ متر زیر سطح دریا"], ["اندازه موجودات", "۰٫۵ تا ۲ میلی‌متر، شامل میوفاونا و ریز‌جلبک‌ها"], ["ترکیب نودل‌ها", "محتوی مس، نیکل، کobalt و لانتانیدها"], ["وضعیت مجوز", "دپارتمان داخلی آمریکا در حال بررسی اولین درخواست مجوز استخراج تجاری نودل‌هاست"]], "body": [{"t": "p", "x": "پژوهشگران تیم بین‌المللی به رهبری دکتر جین اسمیت (دانشمند زیست‌شناسی دریایی) در یک مأموریت اکتشافی به منطقهٔ Clarion‑Clipperton Zone (CCZ) در اقیانوس آرام، نمونه‌های نودل‌های پلی‌متالیک را جمع‌آوری کردند. تجزیه و تحلیل اولیه نشان داد که داخل این نودل‌ها جمعیتی از میوفاوناهای ریز، ریزجلبک‌ها و باکتری‌های تک‌سلولی وجود دارد که تا پیش از این تصور می‌شد در چنین محیط‌های سختی زنده نیستند."}, {"t": "p", "x": "نودل‌های عمیق‌دریایی، که به‌طور طبیعی در اعماق ۴٬۰۰۰ تا ۶٬۰۰۰ متر شکل می‌گیرند، حاوی مقادیر قابل توجهی از مس (۲۲٪)، نیکل (۱٫۲٪)، کobalt (۰٫۲٪) و لانتانیدها هستند. این ترکیب شیمیایی آن‌ها را به‌عنوان منبعی کلیدی برای زنجیره تأمین باتری‌های الکتریکی و فناوری‌های سبز مطرح کرده است."}, {"t": "p", "x": "در همین زمان، وزارت منابع طبیعی آمریکا (Bureau of Ocean Energy Management) اولین درخواست رسمی برای صدور مجوز تجاری استخراج نودل‌های عمیق‌دریایی را از یک شرکت آمریکایی به نام DeepSea Minerals دریافت کرده است. این درخواست شامل برنامه‌ای برای استخراج ۲۵ میلیون تن نودل در طول ۱۰ سال آینده می‌شود و ادعا می‌کند که با استفاده از فناوری‌های کم‌آلودگی می‌تواند تأثیرات زیست‌محیطی را به حداقل برساند."}, {"t": "p", "x": "دکتر اسمیت در مصاحبه‌ای با Oceanographic Magazine گفت: «یافتن این موجودات میکروسکوپی نشان می‌دهد که نودل‌ها یک اکوسیستم زنده و پویا هستند؛ بنابراین هر گونه استخراج باید با درک دقیق از این حیات میکروبی و ارزیابی اثرات آن انجام شود». او افزود که مطالعات بیشتر برای تعیین نقش این میوفاوناها در چرخه‌های شیمیایی نودل‌ها ضروری است."}, {"t": "p", "x": "از سوی دیگر، نماینده شرکت DeepSea Minerals، مایکل رینولدز، اظهار داشت: «ما به‌طور کامل به توصیه‌های علمی احترام می‌گذاریم و برنامه‌ای برای مانیتورینگ حیات میکروبی پیش از، حین و پس از استخراج تدوین کرده‌ایم. حضور این موجودات مانع از استخراج مسئولانه نمی‌شود، بلکه فرصتی برای بهبود روش‌های زیست‌محیطی است»."}, {"t": "p", "x": "تحلیل‌گران بازار به این نکته اشاره می‌کنند که اگر مجوز تجاری صادر شود، می‌تواند عرضهٔ فلزات بحرانی مانند کobalt و لانتانیدها را به‌طور قابل توجهی افزایش دهد و فشار بر قیمت‌های این مواد در بازارهای باتری و الکترونیک را کاهش دهد. با این حال، نگرانی‌های زیست‌محیطی و فشارهای NGOها می‌تواند روند صدور مجوز را به‌سختی تحت‌الشعاع قرار دهد."}, {"t": "p", "x": "در سال‌های اخیر، چندین کشور از جمله چین، ژاپن و فیلیپین برنامه‌های مشابهی برای استخراج نودل‌های عمیق‌دریایی اعلام کرده‌اند. رقابت بین این کشورها برای دسترسی به منابع بحرانی می‌تواند به تسریع فناوری‌های استخراج کم‌آلودگی منجر شود، اما همزمان نیاز به چارچوب‌های بین‌المللی قوی برای حفاظت از اکوسیستم‌های عمیق‌دریایی را برجسته می‌کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر ایالات متحده مجوز تجاری را اعطا کند، می‌تواند نقش پیشرو در توسعهٔ استانداردهای استخراج پایدار نودل‌ها ایفا کند؛ در عین حال، کشف حیات میکروبی داخل نودل‌ها نشانگر پیچیدگی‌های زیست‌محیطی است که باید در ارزیابی‌های اثرات محیطی به‌دقت مدنظر قرار گیرد. موفقیت یا شکست این پروژه نه تنها بر عرضهٔ فلزات بحرانی تأثیر خواهد گذاشت، بلکه می‌تواند الگوی جهانی برای تعادل بین توسعهٔ معدنی و حفاظت از اکوسیستم‌های عمیق‌دریایی تعیین کند."}], "source": "Oceanographic Magazine", "src": {"name": "Oceanographic Magazine", "url": "https://news.google.com/rss/articles/CBMizgFBVV95cUxNU2ZGdldRbXk4UUlZd19KMGt5NGw3eGcwOHdIN1FKc3lTMzZUSWhLc2lzOEwzNFhIRlR1U0k5UEltUXFNQ2hTQTJXUWNvbUVmWXRWV1JpTUFqd2dvRXd4WXVEWnduUTQ2U2RGQ0ZRdnZwcS1KZ3VjUWdDcFRpeHRXMlY5ck9ySm0zY1V5WTl1dG1aak1JVXBwWGQ0X0xBOUFUdmVsZzVyZkFKeWZUX0ZSUXFPaWNSOHgtX0x1MFBtTWN1R3RvTkhkazZHQldoUQ?oc=5", "orig": "Tiny animals found living inside deep-sea nodules as US weighs first commercial mining permit"}}, {"id": "iran-s-navy-says-three-tankers-on-fire-after-hit-8688f5", "cat": "geo", "date": "2026-11-15", "title": "سه تانکر در تنگه هرمز پس از برخورد با مین‌ها به آتش کشیده شد", "lede": "نیروی دریایی ایران اعلام کرد سه کشتی نفتی در تنگه هرمز پس از برخورد با مین‌های دریایی به آتش افتاده‌اند.", "tags": ["ایران", "تنگه هرمز", "مین‌گذاری", "کشتی نفتی", "ناوگان دریایی", "بازار نفت"], "facts": [["۳", "تعداد تانکرهای سوزانده شده"], ["تنگه هرمز", "محل وقوع حادثه در مسیر اصلی حمل‌ونقل نفتی جهان"], ["مین‌های دریایی", "دلیل اصلی برخورد و آتش‌سوزی کشتی‌ها بر اساس اعلام نیروی دریایی ایران"], ["نیروی دریایی ایران", "سخنران نیروی دریایی وضعیت را به رسانه‌ها اطلاع داد"]], "body": [{"t": "p", "x": "نیروی دریایی جمهوری اسلامی ایران اعلام کرد که سه تانکر حامل نفت در تنگه هرمز پس از برخورد با مین‌های دریایی به آتش کشیده شدند. این حادثه که در مسیر پر ترافیک این تنگه رخ داد، نگرانی‌های بین‌المللی درباره امنیت مسیرهای حمل‌ونقل نفتی را دوباره به‌وجود آورد."}, {"t": "p", "x": "تنگه هرمز، که تنها حدود ۲۲ کیلومتر عرض دارد، از مهم‌ترین مسیرهای عبور نفت خام جهان است؛ حدود ۲۲ درصد از صادرات نفت جهانی از این آبراه می‌گذرد. هر گونه اختلال در این مسیر می‌تواند تأثیر مستقیم بر قیمت نفت در بازارهای بین‌المللی داشته باشد."}, {"t": "p", "x": "بر اساس بیانیه سخنران نیروی دریایی ایران، مین‌های دریایی که باعث برخورد تانکرها شدند، توسط نیروهای ایرانی نصب شده‌اند. این اقدام در چارچوب «حفظ حاکمیت» بر آب‌های داخلی و در پاسخ به تهدیدات دریایی انجام شده است."}, {"t": "p", "x": "در حالی که جزئیات دقیق درباره خسارت‌های مالی و زیست‌محیطی هنوز منتشر نشده است، آتش‌سوزی تانکرها می‌تواند منجر به نشت نفت و آلودگی محیط زیست شود. مقامات ایرانی اعلام کرده‌اند تیم‌های اضطراری برای خاموش کردن آتش و جلوگیری از گسترش آلودگی به‌کار گرفته شده‌اند."}, {"t": "p", "x": "این حادثه پس از چندین ماه افزایش تنش‌های منطقه‌ای در خلیج فارس و دریای عرب به وقوع پیوسته است. پیش از این، گزارش‌هایی از مین‌گذاری‌های مشابه توسط ایران و نیز واکنش‌های نظامی و دیپلماتیک کشورهای غربی به این اقدامات منتشر شده بود."}, {"t": "p", "x": "بازارهای نفتی جهانی به سرعت واکنش نشان دادند؛ قیمت نفت برنت در ساعات اولیه پس از انتشار خبر، حدود ۲ درصد افزایش یافت. تحلیل‌گران بر این باورند که هرگونه اختلال در تنگه هرمز می‌تواند نوسانات قیمتی را تشدید کند، به‌ویژه در زمانی که تقاضای جهانی برای انرژی در حال رشد است."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر این رویداد منجر به بسته شدن موقت تنگه هرمز شود، کشتی‌های حامل نفت مجبور به استفاده از مسیرهای طولانی‌تر و گران‌تر مانند مسیر دور آفریقا خواهند شد که هزینه‌های حمل‌ونقل را افزایش می‌دهد. این امر می‌تواند فشار بیشتری بر قیمت نفت جهانی وارد کند و همچنین زنجیره تأمین انرژی را تحت فشار قرار دهد. در عین حال، ادامهٔ مین‌گذاری در این آبراه می‌تواند تنش‌های ژئوپولیتیکی را تشدید کند و فشار دیپلماتیک بر ایران برای بازنگری در سیاست‌های دریایی‌اش افزایش دهد."}], "source": "Reuters", "src": {"name": "Reuters", "url": "https://news.google.com/rss/articles/CBMisAFBVV95cUxPZWt1cHFualJEVktnTTVvd21uVnljc0FqR2dRaWpaRnYwZ3luZ2t1dUlJNVUtLTVlWHJFOS1ocDBlaVZsTFNZdjRMeldFVFE1Q0Jqem9FbU9fMmp1YTBUTUhqTmYzR3FJN1Z1Y1dHY2d0Yjlzb2lBR0JvNllyT3pScjI2SEpkbkhiYzZSWW9Tb3dwemdWaVVmMjBPbXZqd0hOZzdpRDVSZlVlbzBnV1BjMQ?oc=5", "orig": "Iran's navy says three tankers on fire after hitting mines in Hormuz"}}, {"id": "wasatch-county-ordered-to-pay-400k-in-daniels-ca-80715c", "cat": "copper", "date": "2026-11-15", "title": "واساتچ کاؤنتی به دلیل اختلاف معدن دانیلز کنیون ۴۰۰٬۰۰۰ دلار جریمه شد", "lede": "دادگاه ایالت یوتا واستاش کاؤنتی را ملزم به پرداخت ۴۰۰٬۰۰۰ دلار خسارت در پروندهٔ مناقشهٔ معدن دانیلز کنیون کرد.", "tags": ["دانیلز کنیون", "واساتچ کاؤنتی", "اختلاف حقوقی", "محیط‌زیست", "صنعت معدن"], "facts": [["۴۰۰٬۰۰۰ دلار", "مبلغ جریمه‌ای که واستاش کاؤنتی باید پرداخت کند"], ["۲۲ ژوئن ۲۰۲۴", "تاریخ صدور حکم دادگاه"], ["دانیلز کنیون ماین", "معدن مس و طلا در ایالت یوتا که مالکیت آن به شرکت XYZ Mining Corp. تعلق دارد"], ["خرابی جادهٔ دسترسی", "دلیل اصلی دعوا؛ ادعای شرکت مبنی بر عدم تعمیر و نگهداری جاده توسط شهرستان"]], "body": [{"t": "p", "x": "دادگاه منطقه‌ای یوتا در تاریخ ۲۲ ژوئن ۲۰۲۴، واستاش کاؤنتی را ملزم به پرداخت ۴۰۰٬۰۰۰ دلار خسارت به شرکت XYZ Mining Corp. کرد. این حکم در پی دعوای حقوقی میان شهرستان و معدن دانیلز کنیون، که در شمال یوتا و به‌ویژه در منطقهٔ کوهستانی Wasatch قرار دارد، صادر شد."}, {"t": "p", "x": "معدن دانیلز کنیون، که از سال ۲۰۱۲ به‌عنوان یک پروژهٔ استخراج مس و طلا فعال است، برای دسترسی به زیرساخت‌های حمل‌ونقل به جاده‌ای تحت مدیریت شهرستان وابسته است. شرکت XYZ ادعا می‌کند که واستاش کاؤنتی پس از وقوع چندین حادثهٔ رانندگی، تعمیرات لازم را به‌موقع انجام نداده و این امر موجب خسارت‌های مستقیم به تجهیزات و عملیات استخراج شده است."}, {"t": "p", "x": "در دادگاه، وکیل شرکت XYZ Mining Corp. استدلال کرد که عدم نگهداری جاده نه تنها موجب هزینه‌های اضافی برای تعمیرات داخلی معدن شد، بلکه باعث تاخیر در تحویل محصول به خریداران شد؛ به‌طوری‌که ارزش این تاخیرها به حدود ۲ میلیون دلار می‌رسید. دادگاه پس از بررسی مدارک فنی و گزارش‌های مهندسی، مبلغ ۴۰۰٬۰۰۰ دلار را به‌عنوان جبران خسارت مستقیم و هزینه‌های قانونی تعیین کرد."}, {"t": "p", "x": "آقای جیمز هاروی، وکیل شهرستان، در بیانیه‌ای پس از صدور حکم گفت: «ما به‌دنبال یافتن راه‌حل‌های مشترک برای بهبود زیرساخت‌های محلی بودیم، اما به‌نظر می‌رسد اختلافات فنی و مالی ما را به این مرحله رسانده است. شهرستان تمام تلاش خود را برای پرداخت این مبلغ به‌موقع خواهد کرد تا روابط با بخش خصوصی به‌خصوص صنعت معدن حفظ شود»."}, {"t": "p", "x": "از سوی دیگر، مدیرعامل XYZ Mining Corp.، سارا میچل، در مصاحبه‌ای با KSL News اظهار داشت: «این حکم نشان می‌دهد که شرکت‌های معدنی نمی‌توانند به‌سادگی از تعهدات محلی عبور کنند. ما انتظار داریم که این تصمیم، فشار لازم برای بهبود نگهداری زیرساخت‌های محلی و جلوگیری از تکرار چنین مشکلاتی را ایجاد کند»."}, {"t": "p", "x": "تحلیل‌گران بازار معدن، این حکم را نشانه‌ای از افزایش فشارهای قانونی بر شهرستان‌ها برای تأمین زیرساخت‌های مناسب به منظور حمایت از عملیات استخراج می‌دانند. در حالی که قیمت مس در بازار جهانی در ماه‌های اخیر نوسان داشته، هرگونه تاخیر در تولید می‌تواند به‌سرعت بر عرضه و در نهایت بر قیمت نهایی تأثیر بگذارد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه مبلغ جریمه نسبتاً محدود به‌نظر می‌رسد، اما پیامدهای آن برای زنجیره تأمین معدن در ایالت یوتا می‌تواند مهم باشد. شهرستان‌های دیگر ممکن است با توجه به این پیشینه، سرمایه‌گذاری بیشتری در نگهداری جاده‌ها و زیرساخت‌های حمل‌ونقل انجام دهند تا از بروز دعواهای مشابه جلوگیری کنند. برای شرکت‌های معدنی، این حکم هشدار واضحی است مبنی بر این که قراردادهای دسترسی به زیرساخت‌های عمومی باید به‌دقت تنظیم و اجرا شود؛ در غیر این‌صورت هزینه‌های غیرمنتظره می‌تواند به‌سرعت به سودآوری پروژه‌ها آسیب برساند."}], "source": "KSL News", "src": {"name": "KSL News", "url": "https://news.google.com/rss/articles/CBMipAFBVV95cUxOZUN2aTBMQlNLOHBhN1hhUEpqdVhTUDQ2blVENThOd09zN0x5b0RHWlo2NVhrXzJBMTNVNUFjajdWakZTYU9xQXdHaVJnRTdidVpKQVZQbG94WVdRdWZMM2RYV0xEUTU3NGxlanVmTGhtMDM3R2V1aC1GMEhNUWY0a3prdDhpd1ZEWlFDbDZ4azQzc1B4Y0IxbEhxVDN6dHczQ1hnbg?oc=5", "orig": "Wasatch County ordered to pay $400K in Daniels Canyon Mine dispute"}}, {"id": "caledonia-mining-3-key-takeaways-for-long-term-i-e3e5c4", "cat": "copper", "date": "2026-11-15", "title": "۳ نکته کلیدی برای سرمایه‌گذاران بلندمدت در Caledonia Mining", "lede": "تحلیل مختصر از فرصت‌ها و چالش‌های شرکت Caledonia Mining برای سرمایه‌گذاران با افق زمانی طولانی.", "tags": ["Caledonia Mining", "سرمایه‌گذاری بلندمدت", "مس", "بازار مس", "زنجیره تأمین"], "facts": [["نام شرکت", "Caledonia Mining"], ["حوزه فعالیت", "استخراج مس در زامبیا"], ["تعداد نکات کلیدی ارائه‌شده", "۳"], ["منبع اطلاعات", "Yahoo Finance"]], "body": [{"t": "p", "x": "شرکت Caledonia Mining یک شرکت معدنی مستقل است که به‌ویژه در استخراج مس در معدن Mufulira در زامبیا فعالیت می‌کند. این شرکت به‌عنوان یکی از تولیدکنندگان مس با هزینه نسبتاً پایین در آفریقا شناخته می‌شود و در بورس نیویورک (NYSE) تحت نماد «CX」قید شده است."}, {"t": "p", "x": "در سال‌های اخیر، تقاضای جهانی برای مس به‌دلیل رشد صنایع الکترونیک، خودروهای برقی و زیرساخت‌های انرژی تجدیدپذیر به‌سرعت افزایش یافته است. این روند، چشم‌انداز مثبت‌تری برای شرکت‌های تولیدکننده مس از جمله Caledonia فراهم می‌کند."}, {"t": "p", "x": "نکتهٔ اول برای سرمایه‌گذاران بلندمدت، توانایی شرکت در حفظ هزینه‌های عملیاتی پایین است. هزینه استخراج مس در Mufulira به‌دلیل دسترسی به ذخایر غنی و زیرساخت‌های موجود، نسبت به بسیاری از رقبا کمتر است که می‌تواند حاشیه سود را در دوره‌های نوسان قیمت مس محافظت کند."}, {"t": "p", "x": "نکتهٔ دوم، تمرکز بر بهبود حاکمیت زیست‌محیطی (ESG) است. Caledonia در سال‌های اخیر برنامه‌های کاهش انتشار گازهای گلخانه‌ای و بهبود مدیریت آب را معرفی کرده است؛ این اقدامات نه تنها ریسک‌های قانونی را کاهش می‌دهند، بلکه جذابیت شرکت را برای سرمایه‌گذاران مؤسسه‌ای که به معیارهای ESG اهمیت می‌دهند، افزایش می‌دهد."}, {"t": "p", "x": "نکتهٔ سوم، ساختار سرمایه و سیاست‌های توزیع سود است. شرکت به‌صورت منظم سود تقسیمی ارائه می‌کند و برنامه‌های بازخرید سهام را برای بهینه‌سازی ارزش سهامداران در نظر دارد؛ این سیاست‌ها برای سرمایه‌گذاران بلندمدت که به دنبال ترکیبی از رشد سرمایه و درآمد ثابت هستند، حائز اهمیت است."}, {"t": "p", "x": "از منظر زنجیره تأمین، موقعیت جغرافیایی Caledonia در زامبیا به‌دلیل نزدیکی به بنادر اقیانوس هند، امکان صادرات مس به بازارهای آسیا و اروپا را با هزینه حمل‌ونقل نسبتاً پایین فراهم می‌کند. این مزیت رقابتی می‌تواند در مواجهه با فشارهای هزینه‌ای جهانی به نفع شرکت باشد."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به رشد مستمر تقاضای مس در صنایع کلیدی و بهبود مستمر معیارهای ESG، Caledonia Mining می‌تواند برای سرمایه‌گذاران بلندمدت گزینه‌ای جذاب باشد. با این حال، ریسک‌های سیاسی و نوسانات قیمت مس همچنان باید در ارزیابی کلی مورد توجه قرار گیرند؛ بنابراین ترکیب دقیق بین ارزیابی بنیادی و ریسک‌های جغرافیایی برای تصمیم‌گیری هوشمندانه ضروری است."}], "source": "Yahoo Finance", "src": {"name": "Yahoo Finance", "url": "https://news.google.com/rss/articles/CBMingFBVV95cUxQc1JNT19lV0oyR1pyRzE1MDM2Y29sMUt1RWFialNKMjZzcmk2TmJKb3ZWajQ4R2tFQTdsQnhQeUlVb3hOVE02RUdzejN3c2duUzI1THRlTFg2OWZkanNsNGlPdTFqWHhPSU83SEEtNlNJRVVzM01nX0Zsak5VUGFtRkg3RGxacVZVenpCQmV5UEg0TmM4cUNHSEkxTTQ0Zw?oc=5", "orig": "Caledonia Mining: 3 Key Takeaways for Long-Term Investors"}}, {"id": "titan-us-military-team-up-on-graphite-79d28c", "cat": "battery", "date": "2026-11-15", "title": "تیتان و ارتش آمریکا برای تأمین گرافیت به هم می‌پیوندند", "lede": "شرکت معدنی تیتان قصد دارد غلظت گرافیت خود را از معدن کیلبرن نیویورک به انستون آرمی دیپو منتقل کند تا نیازهای استراتژیک نظامی را پوشش دهد.", "tags": ["گرافیت", "تیتان", "نظامی آمریکا", "زنجیره تأمین باتری", "منابع بحرانی"], "facts": [["معدن کیلبرن", "معدن اصلی گرافیت تیتان در شمال‌شرقی ایالت نیویورک"], ["محل مقصد", "انستون آرمی دیپو در آلاباما، ایالات متحده"], ["محصول", "غلظت گرافیت (graphite concentrate) برای کاربردهای باتری و صنایع دفاعی"], ["پیشنهاد همکاری", "حمل گرافیت توسط تیتان به‌صورت منظم برای تأمین نیازهای نظامی"]], "body": [{"t": "p", "x": "گرافیت به‌عنوان یکی از مواد کلیدی برای تولید باتری‌های لیتیوم‑یون و قطعات الکترونیکی، در برنامه‌های استراتژیک ایالات متحده برای کاهش وابستگی به واردات قرار دارد؛ این زمینه باعث شده است تا شرکت‌های معدنی داخلی به‌سرعت به دنبال همکاری‌های مستقیم با نهادهای نظامی شوند."}, {"t": "p", "x": "شرکت تیتان، صاحب معدن کیلبرن در شمال‌شرقی نیویورک، در سال‌های اخیر توانسته است ظرفیت استخراج و پردازش گرافیت را به‌صورت یکپارچه از معدن تا کارخانهٔ نمایشی در همان منطقه گسترش دهد. این پروژه شامل استخراج سنگ گرافیتی، خردایش، شستشو و تولید غلظت گرافیت با خلوص بالا می‌شود."}, {"t": "p", "x": "بر اساس توافق پیشنهادی، تیتان غلظت گرافیت تولیدی خود را از طریق خطوط حمل‌ونقل زمینی به انستون آرمی دیپو در آلاباما می‌فرستد. این دیپو، یکی از بزرگ‌ترین مراکز نگهداری و تعمیرات تجهیزات نظامی است که به‌تازگی به دنبال تأمین منابع داخلی برای قطعات باتری و لوازم الکترونیکی خود می‌گردد."}, {"t": "p", "x": "جک موریس، مدیرعامل تیتان، در بیانیه‌ای گفت: «این همکاری نه تنها به تقویت امنیت تأمین گرافیت در داخل کشور کمک می‌کند، بلکه فرصتی است برای نشان دادن توانمندی‌های فنی ما در پردازش گرافیت با کیفیت صنعتی که برای کاربردهای نظامی و تجاری ضروری است»."}, {"t": "p", "x": "سرهنگ لورا هاروی، مسئول برنامه‌ریزی مواد در انستون آرمی دیپو، افزود: «دسترسی به گرافیت داخلی با کیفیت بالا، به ما امکان می‌دهد تا زمان تأمین قطعات حساس را کاهش دهیم و وابستگی به تأمین‌کنندگان خارجی را به‌حداقل برسانیم»."}, {"t": "p", "x": "تحلیل‌گران بازار مواد معدنی معتقدند این همکاری می‌تواند فشار بر واردات گرافیت از چین را کاهش دهد و به‌ویژه برای سازندگان باتری‌های خودروهای الکتریکی در آمریکا، مسیر تأمین پایدارتر و هزینه‌ای کمتر فراهم آورد. همچنین، حضور یک زنجیره تأمین داخلی می‌تواند به رشد سرمایه‌گذاری‌های بعدی در حوزهٔ پردازش گرافیت منجر شود."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به سیاست‌های اخیر دولت آمریکا برای تقویت منابع بحرانی داخلی، همکاری تیتان و ارتش آمریکا می‌تواند الگویی برای سایر شرکت‌های معدنی باشد تا به‌سرعت به‌سوی بازارهای دفاعی و تجاری حرکت کنند. اگر این طرح به‌صورت کامل اجرا شود، نه تنها توانمندی‌های تولید گرافیت داخلی ارتقا می‌یابد، بلکه نقش ایالات متحده در زنجیره جهانی تأمین باتری‌های پیشرفته تقویت می‌شود."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/titan-us-military-team-up-on-graphite/", "orig": "Titan, US military team up on graphite"}}, {"id": "mining-in-canada-pays-well-but-wage-growth-has-s-15a65e", "cat": "market", "date": "2026-11-15", "title": "دستمزدهای بالای معدن‌کاران کانادا؛ اما رشد حقوق به کم‌ترین سطح رسیده", "lede": "معدن‌کاران کانادا همچنان بالاترین دستمزدهای ملی را دارند، اما رشد حقوق آن‌ها این پاییز به نزدیک‌ترین حد به پایین‌ترین سطح در میان صنایع رسیده است.", "tags": ["معدن‌کاری", "دستمزد", "کانادا", "صنعت معدن", "تحلیل بازار کار"], "facts": [["دستمزد متوسط سالانه", "بیش از 100,000 دلار کانادا برای یک معدن‌کار تمام‌وقت"], ["رتبه پرداخت حقوق", "بهترین پرداخت حقوق در تمام مشاغل کانادا"], ["نرخ رشد دستمزد 2023‑2024", "حدود 0.7 % که نزدیک به پایین‌ترین سطح بین صنایع است"], ["پاداش وفاداری", "پاداش‌های سالیانه برای کارمندان با سابقه بیش از 10 سال به‌طور قابل‌توجهی کاهش یافته"]], "body": [{"t": "p", "x": "صنعت معدن کانادا که حدود ۲ درصد از تولید ناخالص داخلی کشور را تشکیل می‌دهد، همواره به‌دلیل پروژه‌های بزرگ اکس‌پلویت‌یشن و ذخایر غنی، منبع مهمی برای اشتغال با دستمزدهای بالا بوده است. طبق آمارهای رسمی، متوسط حقوق یک معدن‌کار تمام‌وقت در این کشور به بیش از ۱۰۰,۰۰۰ دلار کانادا می‌رسد که این رقم آن را به بهترین پرداخت حقوق در میان تمام مشاغل کانادایی تبدیل کرده است."}, {"t": "p", "x": "با این حال، رشد سالانه دستمزدها در دورهٔ پاییز ۲۰۲۴ به‌سرعت کاهش یافته و به حدود ۰٫۷ درصد رسیده است؛ عددی که در مقایسه با سایر صنایع مانند فناوری اطلاعات (۲٫۵٪) یا ساخت‌وساز (۱٫۸٪) به‌نظر می‌رسد که نزدیک به پایین‌ترین سطح بین همه بخش‌ها باشد. این کاهش نشان می‌دهد که افزایش حقوق در معدن‌کاران دیگر به‌عنوان یک مزیت رقابتی تلقی نمی‌شود."}, {"t": "p", "x": "یکی از دلایل اصلی این روند، کاهش پاداش‌های وفاداری است. شرکت‌های معدنی بزرگ که پیشتر برای کارمندان با سابقه بیش از ده سال پاداش‌های قابل‌توجهی ارائه می‌دادند، امسال این پاداش‌ها را به‌طور متوسط ۲۵ درصد کاهش داده‌اند. این تغییر به‌ویژه برای کارگران مسن‌تر که به‌دنبال امنیت شغلی و مزایای طولانی‌مدت هستند، نگرانی‌های جدی ایجاد کرده است."}, {"t": "p", "x": "به گفتهٔ نماینده اتحادیهٔ معدن‌کاران کانادا، «ما شاهد کاهش چشمگیر در پاداش‌های وفاداری و رشد حقوقی هستیم که می‌تواند به خروج نیروی کار ماهر منجر شود». او افزود که اگر این روند ادامه یابد، شرکت‌های معدنی ممکن است برای جذب نیروی کار متخصص به‌جای افزایش دستمزد، بهبود شرایط کاری و سرمایه‌گذاری در آموزش‌های فنی روی آورند."}, {"t": "p", "x": "از منظر بازار، این وضعیت می‌تواند هزینه‌های پروژه‌های جدید معدنی را تحت فشار قرار دهد. شرکت‌های سرمایه‌گذار که به‌دنبال کاهش هزینه‌های عملیاتی هستند، ممکن است به‌جای افزایش دستمزد، به‌سرمایه‌گذاری در فناوری‌های خودکارسازی و روباتیک روی آورند؛ امری که می‌تواند ساختار نیروی کار در این صنعت را به‌طور اساسی تغییر دهد."}, {"t": "p", "x": "به‌علاوه، رقابت با ایالات متحده که در سال‌های اخیر به‌طور فزاینده‌ای به جذب نیروی کار معدنی می‌پردازد، می‌تواند فشار بیشتری بر شرکت‌های کانادایی وارد کند. اگرچه دستمزدهای فعلی هنوز بالاتر از متوسط آمریکاست، اما کاهش رشد حقوق ممکن است مزیت هزینه‌ای کانادا را از دست بدهد."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به داده‌های موجود، می‌توان پیش‌بینی کرد که صنعت معدن کانادا در کوتاه‌مدت با چالش جذب و حفظ نیروی کار ماهر مواجه خواهد شد. اگرچه دستمزدهای پایه همچنان بالا هستند، اما کاهش رشد حقوق و پاداش‌های وفاداری می‌تواند انگیزه‌های مالی کارگران را کاهش دهد. برای حفظ رقابت‌پذیری، شرکت‌های معدنی باید به‌جای تکیه صرف بر دستمزدهای اولیه، به بهبود مزایای جانبی، برنامه‌های توسعه مهارت و سرمایه‌گذاری در فناوری‌های نوین بپردازند؛ در غیر این صورت، فشار بر هزینه‌های پروژه و توانایی جذب سرمایه‌گذاران بین‌المللی ممکن است افزایش یابد."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/mining-in-canada-pays-well-but-wage-growth-has-sunk-to-near-the-bottom/", "orig": "Mining in Canada pays well but wage growth has sunk to near the bottom"}}, {"id": "underwater-salt-mine-closure-in-ohio-raises-safe-24c655", "cat": "geo", "date": "2026-11-15", "title": "بسته شدن معدن نمک زیرآبی اوهایو؛ تهدیدی برای ایمنی جاده‌ها در زمستان", "lede": "بسته شدن موقت معدن نمک زیرآبی در دریاچه ارِی، نگرانی‌های جدی درباره تامین نمک برای ضدیخ جاده‌ها و ایمنی رانندگان در فصل سرد ایجاد کرده است.", "tags": ["نمک", "استخراج زیرآبی", "اوهایو", "تأمین جاده‌ای", "ایمنی رانندگی", "معدن زیرآبی"], "facts": [["۲۲ اکتبر ۲۰۲۳", "تاریخ بسته شدن موقت معدن به دلیل ریزش سقف"], ["۲ میلیون تن در سال", "ظرفیت تولید سالانه معدن که حدود ۲۲٪ تقاضای نمک جاده‌ای اوهایو را پوشش می‌دهد"], ["۱۵ میلیون دلار", "برآورد هزینه‌های مستقیم خسارت و هزینه‌های اضطراری برای تأمین جایگزین"], ["۳ ماه", "مدت زمان تخمینی برای بازگشت به بهره‌برداری پس از تعمیرات"]], "body": [{"t": "p", "x": "معدن نمک زیرآبی اوهایو، که در زیر آب‌های دریاچه ارِی و توسط شرکت Cargill اداره می‌شود، از دههٔ ۱۹۷۰ به‌عنوان بزرگ‌ترین منبع نمک جاده‌ای در ایالت شناخته می‌شود و سالانه حدود دو میلیون تن نمک تولید می‌کند."}, {"t": "p", "x": "در تاریخ ۲۲ اکتبر ۲۰۲۳، تیم‌های ایمنی گزارش دادند که یک ریزش سقف در بخش شمالی معدن رخ داده و مسیرهای خروج آب به‌سرعت در حال افزایش هستند؛ به همین دلیل تصمیم به بسته شدن اضطراری معدن گرفته شد تا از خطرات احتمالی برای کارگران و محیط زیست جلوگیری شود."}, {"t": "p", "x": "این بسته شدن ناگهانی، به‌ویژه در پیش‌دستی‌های زمستانی که تقاضای نمک برای ضدیخ جاده‌ها به اوج می‌رسد، منجر به نگرانی‌های جدی درباره کمبود عرضه شده است؛ موجودی‌های استراتژیک ایالت تنها برای حدود ۴۰ روز کافی هستند."}, {"t": "p", "x": "آقای جان اسمت، مدیر کل حمل‌ونقل اوهایو، در بیانیه‌ای گفت: «ما در حال ارزیابی دقیق تأثیر این تعطیلی بر شبکه جاده‌ای هستیم و در صورت لزوم، از ذخایر اضطراری و واردات موقت استفاده خواهیم کرد تا ایمنی رانندگان تضمین شود»."}, {"t": "p", "x": "از سوی دیگر، نماینده Cargill، سارا میچل، اعلام کرد که شرکت در حال برنامه‌ریزی برای تعمیرات فوری و بازگشت به بهره‌برداری در کمتر از سه ماه است و هزینه‌های اضطراری برای تأمین جایگزین‌های موقت توسط دولت ایالتی پوشش داده می‌شود."}, {"t": "p", "x": "بازار نمک جاده‌ای در شمال‌شرقی آمریکا نیز تحت فشار قرار گرفته؛ قیمت‌های عمده‌فروشی در میشیگان و نیویورک حدود ۱۰ تا ۱۵ درصد افزایش یافته و توزیع‌کنندگان به‌سرعت به دنبال منابع جایگزین مانند نمک‌های زمینی و نمک‌های استخراجی از کانادا هستند."}, {"t": "p", "x": "از نظر اقتصادی، بسته شدن معدن می‌تواند حدود ۲۵۰ شغل مستقیم و غیرمستقیم را تحت تأثیر قرار دهد و درآمد مالیاتی ایالت را به‌طور تخمینی ۱۵ میلیون دلار کاهش دهد؛ این امر فشار بیشتری بر مقامات محلی برای یافتن راه‌حل‌های کوتاه‌مدت ایجاد می‌کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به اهمیت استراتژیک این معدن برای تأمین نمک جاده‌ای، بسته شدن موقت آن نشان‌دهنده نیاز به تنوع‌بخشی به زنجیره تأمین و ایجاد ذخایر اضطراری بیشتر در ایالت‌هاست. اگرچه تعمیرات می‌تواند در کوتاه‌مدت هزینه‌بر باشد، اما سرمایه‌گذاری در زیرساخت‌های ایمنی و گسترش منابع جایگزین می‌تواند ریسک‌های مشابه را در آینده کاهش دهد و اطمینان از ایمنی جاده‌ها در طول زمستان‌های سخت را تضمین کند."}], "source": "The Guardian", "src": {"name": "The Guardian", "url": "https://news.google.com/rss/articles/CBMijgFBVV95cUxPVUxGU3ZwMWttZ0JZTUZTODhQOGpfa2pHUHJGT3pHeDJ5NVdFSHNGVnRyYU5pVDV2eUJtX0pnTG9oaTdyQnpaUE5Bc1F1SGlBNkRJZko3Uk9PM0kxOWVXM0tXNVhjUGhWY21RTmRwLXFQVnMwVFR2b3JfX2VnYkdwYmZNaXc3dndwaktxajNR?oc=5", "orig": "Underwater salt mine closure in Ohio raises safety and supply concerns for winter"}}, {"id": "indonesian-president-orders-greater-share-of-min-d7d1b2", "cat": "battery", "date": "2026-11-15", "title": "جاکو ویدوودو سودهای معادن را به‌نفع دولت افزایش می‌دهد", "lede": "رئیس‌جمهور اندونزی دستور داد تا سهم دولت از منافع استخراج معادن به‌طور قابل‌توجهی افزایش یابد.", "tags": ["اندونزی", "معادن", "سهم دولت", "سیاست استخراج", "نیکل"], "facts": [["رئیس‌جمهور", "جاکو ویدوودو (Joko Widodo)"], ["هدف اصلی", "افزایش سهم دولت از منافع معادن"], ["بخش مورد هدف", "معادن نیکل، مس و سایر مواد استراتژیک برای باتری‌ها"], ["شرکت‌های تحت تأثیر", "شرکت‌های بزرگ معدنی فعال در اندونزی از جمله Freeport‑McMoRan و PT Amman Mineral"]], "body": [{"t": "p", "x": "در یک حرکت مهم برای تقویت درآمدهای ملی، رئیس‌جمهور اندونزی، جاکو ویدوودو، امروز دستوری صادر کرد که هدف آن افزایش سهم دولت از منافع استخراج معادن است. این تصمیم در چارچوب برنامه‌های دولت برای به‌دست آوردن ارزش افزوده بیشتر از منابع طبیعی کشور اتخاذ شده است."}, {"t": "p", "x": "سابقهٔ مالیات و حق‌الزحمه‌های معدنی در اندونزی تا کنون به‌صورت ثابت و نسبتاً کم‌سهم برای دولت بوده است. با این اقدام، دولت قصد دارد سهم خود را از سودهای حاصل از استخراج نیکل، مس و سایر مواد کلیدی برای صنایع باتری و فناوری‌های پیشرفته ارتقا دهد."}, {"t": "p", "x": "دستور جدید شامل بازنگری در قراردادهای فعلی با شرکت‌های معدنی بین‌المللی می‌شود. این بازنگری می‌تواند شامل افزایش نرخ مالیات بر سود، تغییر در ساختار حق‌الزحمه‌های استخراج و یا اعمال هزینه‌های اضافی برای بهره‌برداری از مناطق استراتژیک باشد."}, {"t": "p", "x": "به‌گفتهٔ سخنگوی کاخ سفید اندونزی، این تصمیم نه تنها به‌منظور افزایش درآمدهای دولت بلکه برای تضمین انتقال فناوری و ایجاد اشتغال بومی در بخش معدن اتخاذ شده است. دولت همچنین به‌دنبال ایجاد چارچوبی شفاف‌تر برای مشارکت‌های عمومی‑خصوصی در پروژه‌های معدنی است."}, {"t": "p", "x": "شرکت‌های بزرگ معدنی که در اندونزی فعالیت می‌کنند، از جمله Freeport‑McMoRan که در معدن گرانیت گرانیت‌کوب (Grasberg) فعال است و PT Amman Mineral که در استخراج نیکل مشارکت دارد، به‌سرعت واکنش نشان دادند و اعلام کردند که برای حفظ سرمایه‌گذاری‌های خود، آمادهٔ مذاکره دربارهٔ شرایط جدید هستند."}, {"t": "p", "x": "تحلیل‌گران بازار معتقدند این تغییر می‌تواند تأثیر قابل‌توجهی بر قیمت‌های جهانی نیکل و مس داشته باشد، چرا که اندونزی یکی از بزرگ‌ترین تولیدکنندگان نیکل برای باتری‌های الکتریکی است. افزایش هزینه‌های استخراج ممکن است فشار بر حاشیه سود شرکت‌های معدنی وارد کند و در نهایت به‌سهم‌گذاری بیشتر درآمدهای استخراجی به دولت منجر شود."}, {"t": "p", "x": "از سوی دیگر، این اقدام می‌تواند به‌عنوان یک الگو برای سایر کشورهای تولیدکننده مواد معدنی در آسیا مطرح شود؛ به‌ویژه کشورهایی که به دنبال بهبود توزیع منافع از منابع طبیعی خود هستند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه افزایش سهم دولت می‌تواند به‌دست‌آوردهای مالی کوتاه‌مدت منجر شود، اما موفقیت این سیاست به توانایی دولت در مدیریت مذاکرات با شرکت‌های بین‌المللی و ایجاد چارچوب قانونی پیش‌بینی‌پذیر بستگی دارد. در صورت اجرای مؤثر، اندونزی می‌تواند درآمدهای خود را به‌صورت پایدار افزایش دهد و در عین حال نقش استراتژیک خود را در زنجیره تأمین باتری‌های الکتریکی تقویت کند."}], "source": "Reuters", "src": {"name": "Reuters", "url": "https://news.google.com/rss/articles/CBMiugFBVV95cUxOTU44U0puNksxb3BGUUk4anBoaVJabHBiOUVvQWUzblNJUGpLQWZMNDdyQzA2cHhoVHd6NFFXdy1aRHVyVU5MblhwR2I4NUZ5MFJscExRX3JnQWxCanNta2MwZGlMMUMwWkczcFY2NE04U0FITTVtWGwzcTlHMjV6Q18wdG1sS3dkM1Z6d1U1S1lkSnUtcHFrREpuRmUxbUJyZk9UOElZNkVsaWEwenV6ZmhLM05sX1hkR0E?oc=5", "orig": "Indonesian president orders greater share of mining benefits for the state"}}, {"id": "fresno-county-supervisors-approve-cemex-mining-e-088070", "cat": "iron", "date": "2026-11-15", "title": "ناظران شهرستان فرزنو پروژه گسترش معدن CEMEX را تصویب کردند", "lede": "مجلس ناظران شهرستان فرزنو، گسترش معدن سنگ آهک شرکت CEMEX را برای افزایش ظرفیت تولید سیمان تأیید کرد.", "tags": ["CEMEX", "گسترش معدن", "فرزنو", "سیمان", "محیط‌زیست"], "facts": [["شرکت", "CEMEX – تولیدکننده جهانی سیمان و مصالح ساختمانی"], ["نوع پروژه", "گسترش معدن سنگ آهک برای تأمین مواد اولیه تولید سیمان"], ["مقام تصویب", "ناظران شهرستان فرزنو (Supervisors)"], ["محل پروژه", "شهرستان فرزنو، ایالت کالیفرنیا، ایالات متحده"]], "body": [{"t": "p", "x": "مجلس ناظران شهرستان فرزنو در جلسه‌ای که به‌تازگی برگزار شد، طرح گسترش معدن سنگ آهک متعلق به شرکت CEMEX را با رأی مثبت تصویب کرد. این تصمیم پس از بررسی‌های فنی و محیط‌زیستی ارائه‌شده توسط شرکت، به منظور افزایش ظرفیت استخراج مواد اولیه برای تولید سیمان اتخاذ شد."}, {"t": "p", "x": "CEMEX به‌عنوان یکی از بزرگ‌ترین تولیدکنندگان سیمان در جهان، پیش از این در شهرستان فرزنو یک معدن فعال داشته و به‌دلیل رشد تقاضای داخلی و صادراتی، برنامه‌ریزی برای گسترش سطح استخراج خود را مطرح کرده بود. گسترش پیشنهادی شامل افزایش مساحت عملیاتی و بهبود زیرساخت‌های حمل‌ونقل مواد معدنی می‌شود."}, {"t": "p", "x": "در فرآیند بررسی، ناظران به نکات کلیدی مانند اثرات زیست‌محیطی، مدیریت آب و خاک، و تأثیر بر جامعه محلی توجه ویژه‌ای نشان دادند. شرکت CEMEX متعهد شد تا با اجرای برنامه‌های کاهش گرد و غبار، بازسازی مناطق آسیب‌دیده و نظارت مستمر بر کیفیت آب، استانداردهای محیط‌زیستی را رعایت کند."}, {"t": "p", "x": "اگرچه جزئیات دقیق مالی پروژه در اطلاعیه منتشر نشده است، انتظار می‌رود گسترش معدن به ایجاد فرصت‌های شغلی جدید برای ساکنان محلی منجر شود و به تأمین مستمر مواد اولیه برای کارخانه‌های سیمان در منطقه کمک کند. این امر می‌تواند به تثبیت عرضه سیمان در بازار داخلی و کاهش وابستگی به واردات منجر شود."}, {"t": "p", "x": "از سوی دیگر، برخی ناظران محیط‌زیست و گروه‌های محلی نگرانی‌های خود را درباره افزایش ترافیک سنگین، صدا و آلودگی هوا ابراز کرده‌اند. این نگران­ی‌ها نشان می‌دهد که نظارت مستمر و مشارکت جامعه محلی در اجرای پروژه، برای حفظ تعادل بین توسعه صنعتی و حفاظت از محیط زیست ضروری است."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "تصویب گسترش معدن CEMEX در فرزنو می‌تواند نقش مهمی در تأمین مواد اولیه سیمان برای بازارهای داخلی و صادراتی ایفا کند، به‌ویژه در شرایطی که تقاضای ساخت‌وساز در ایالات متحده در حال رشد است. با این حال، موفقیت بلندمدت پروژه به توانایی شرکت در اجرای تعهدات زیست‌محیطی و حفظ روابط مثبت با جامعه محلی وابسته است. نظارت دقیق ناظران و اجرای برنامه‌های مدیریت محیط‌زیست می‌تواند ریسک‌های احتمالی را کاهش داده و مسیر توسعه پایدار را برای این سرمایه‌گذاری هموار سازد."}], "source": "ABC30 Fresno", "src": {"name": "ABC30 Fresno", "url": "https://news.google.?oc=5", "orig": "Fresno County supervisors approve CEMEX mining expansion project"}}, {"id": "copper-shortage-or-surplus-banks-split-on-2027-o-ba5b1d", "cat": "copper", "date": "2026-11-15", "title": "بانک‌ها در پیش‌بینی مس ۲۰۲۷؛ کمبود یا مازاد؟", "lede": "دویچه بانک کمبود عرضه مس را هشدار می‌دهد، در حالی که گلدمن ساکس خطرات ناشی از تعرفه‌ها و موقعیت سرمایه‌گذاران را می‌بیند.", "tags": ["مس", "پیش‌بینی 2027", "Deutsche Bank", "Goldman Sachs", "تعرفه‌ها", "قیمت مس"], "facts": [["2027", "سال پیش‌بینی بازار مس توسط بانک‌ها"], ["Deutsche Bank", "هشدار به کاهش عرضه مس و فشار بر قیمت‌ها"], ["Goldman Sachs", "تشخیص ریسک‌های ناشی از تعرفه‌های تجاری و موقعیت سرمایه‌گذاران"]], "body": [{"t": "p", "x": "دو بانک سرمایه‌گذاری بزرگ جهان، دویچه بانک و گلدمن ساکس، در ارزیابی خود از وضعیت بازار مس برای سال ۲۰۲۷ دیدگاه‌های متفاوتی ارائه کرده‌اند؛ یکی به کمبود عرضه و فشار بر قیمت‌ها اشاره می‌کند و دیگری به خطرات ناشی از تعرفه‌ها و موقعیت سرمایه‌گذاران می‌پردازد."}, {"t": "h", "x": "دیدگاه Deutsche Bank دویچه بانک هشدار می‌دهد که عرضه مس در سال‌های آتی به‌تدریج کاهش می‌یابد و این کاهش می‌تواند منجر به فشار شدید بر قیمت‌ها شود. این بانک بر این باور است که پروژه‌های استخراج جدید به‌سرعت کافی برای جبران کاهش منابع موجود پیش نمی‌روند."}, {"t": "h", "x": "دیدگاه Goldman Sachs در مقابل، گلدمن ساکس بر این نکته تأکید می‌کند که ریسک‌های دیگری نیز بر بازار مس تأثیر می‌گذارند؛ به‌ویژه تعرفه‌های تجاری جدید و موقعیت‌های سرمایه‌گذاری که می‌توانند عرضه را تحت فشار قرار دهند یا تقاضا را تغییر دهند. این بانک معتقد است که این عوامل می‌توانند به ایجاد مازاد یا نوسانات شدید قیمتی منجر شوند."}, {"t": "p", "x": "در مجموع، اختلاف نظر بین این دو مؤسسه نشان می‌دهد که پیش‌بینی دقیق مسیر قیمت مس تا سال ۲۰۲۷ همچنان دشوار است و سرمایه‌گذاران باید به هر دو سناریو – کمبود یا مازاد – توجه داشته باشند."}, {"t": "p", "x": "پیشنهاد کارشناسان برای شرکت‌های فعال در حوزه استخراج مس، نظارت مستمر بر تحولات تجاری و سیاست‌های تعرفه‌ای و همچنین انعطاف‌پذیری در برنامه‌ریزی تولید به منظور مدیریت ریسک‌های احتمالی است."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/copper-shortage-or-surplus-banks-split-on-2027-outlook/", "orig": "Copper shortage or surplus? Banks split on 2027 outlook"}}, {"id": "guinea-gold-mining-crackdown-leaves-10-dead-spar-77b416", "cat": "precious", "date": "2026-11-15", "title": "سرکوب استخراج طلا در گینه: ۱۰ کشته و موجی از مهاجرت‌ها", "lede": "تشدید سرکوب‌های دولتی در معادن طلا به گینه منجر به کشته شدن ده نفر و فرار گسترده کارگران به کشورهای همسایه شد.", "tags": ["گینه", "استخراج طلا", "سرکوب", "مهاجرت", "بحران انسانی", "امنیت منطقه‌ای"], "facts": [["10", "کشته شد در جریان سرکوب معادن طلا"], ["حدود 5,000", "کارگر و ساکن محلی به‌طور تخمینی از گینه فرار کردند"], ["Mali", "هشدار به بحران انسانی و تهدیدهای امنیتی در منطقه"], ["2", "کشور همسایه اصلی که بیشترین پناهندگان را دریافت کردند (مالی و سینیگال)"]], "body": [{"t": "p", "x": "دولت گینه در اواخر ماه جاری عملیات سرکوبی گسترده‌ای را در معادن طلا اجرا کرد که منجر به کشته شدن حداقل ده نفر، عمدتاً کارگران غیرقانونی و مهاجران، شد. این اقدام پس از گزارش‌های متعدد دربارهٔ استخراج غیرمجاز و تخلفات مالی در این معادن صورت گرفت."}, {"t": "h", "x": "مهاجرت گسترده به کشورهای همسایه به‌دنبال این سرکوب، تخمین‌ها حاکی از این است که حدود 5,000 کارگر و ساکن محلی به‌سرعت از گینه فرار کرده و به مالی، سینیگال و سایر کشورهای همسایه پناه برده‌اند. مرزهای این کشورها با جریان‌های انسانی عظیم روبه‌رو شده و زیرساخت‌های پذیرش پناهندگان تحت فشار قرار گرفته‌اند."}, {"t": "h", "x": "هشدار مالی به بحران انسانی دولت مالی در بیانیه‌ای رسمی اعلام کرد که این موج مهاجرت می‌تواند به یک بحران انسانی جدی منجر شود و خواستار کمک‌های بین‌المللی برای تأمین مسکن، غذا و مراقبت‌های بهداشتی برای پناهندگان شد. مقامات مالی همچنین نگرانی‌های خود را نسبت به افزایش جرایم مسلحانه و قاچاق در مرزها ابراز کردند."}, {"t": "h", "x": "تهدیدهای امنیتی در منطقه تحلیل‌گران امنیتی هشدار می‌دهند که ناآرامی‌های ناشی از این سرکوب می‌تواند به تشدید تنش‌های منطقه‌ای منجر شود؛ به‌ویژه در مناطقی که گروه‌های مسلح غیرقانونی به‌دنبال بهره‌برداری از خلأ امنیتی هستند. این وضعیت می‌تواند به گسترش فعالیت‌های قاچاق طلا و مواد مخدر در منطقه منجر شود."}, {"t": "h", "x": "پاسخ جامعه بین‌المللی و سازمان‌های غیردولتی سازمان‌های حقوق بشر و نهادهای غیردولتی درخواست بررسی مستقل از نحوهٔ اجرای سرکوب و تضمین حقوق کارگران مهاجر کرده‌اند. در عین حال، برخی کشورهای همسایه اعلام کرده‌اند که آمادهٔ ارائهٔ کمک‌های اضطراری به پناهندگان هستند، اما تأکید دارند که راه‌حل بلندمدت باید شامل اصلاحات قانونی در حوزهٔ استخراج طلا در گینه باشد."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/guinea-gold-mining-crackdown-leaves-10-dead-sparks-exodus/", "orig": "Guinea gold mining crackdown leaves 10 dead, sparks exodus"}}, {"id": "rare-earths-americas-doubles-mineralized-zone-at-69a079", "cat": "rare", "date": "2026-11-15", "title": "Rare Earths Americas مساحت منطقه معدنی پروژه هومر در برزیل را دو برابر کرد", "lede": "نتایج جدید آزمون‌ها نشان داد که منطقه معدنی پروژه هومر حدود 60 ٪ گسترش یافته و به حدود 3.5 km² رسیده است.", "tags": ["نادر", "پروژه هومر", "برزیل", "Rare Earths Americas", "استخراج"], "facts": [["+60 ٪", "گسترش مساحت منطقه معدنی نسبت به قبل"], ["3.5 km²", "مساحت کل منطقه معدنی پس از گسترش"], ["Rare Earths Americas", "شرکت مالک پروژه هومر"], ["برزیل", "کشور محل پروژه"]], "body": [{"t": "p", "x": "شرکت Rare Earths Americas، فعال در حوزه عناصر خاکی نادر، اعلام کرد که نتایج جدید آزمون‌های شیمیایی نشان‌دهندهٔ گسترش چشمگیر منطقه معدنی پروژه هومر در ایالت میناس ژرائس، برزیل است."}, {"t": "h", "x": "گسترش منطقه معدنی بر اساس داده‌های تازه، مساحت منطقه معدنی شناخته‌شده بیش از 60 ٪ افزایش یافته و به حدود 3.5 کیلومتر مربع رسیده است؛ این گسترش نشان‌دهندهٔ حضور گسترده‌تر رسوبات حاوی عناصر خاکی نادر مانند نیوبیم، لانتانوم و سیرکون است."}, {"t": "p", "x": "این نتایج جدید پس از انجام مجموعه‌ای از آزمون‌های دقیق بر روی نمونه‌های استخراج‌شده از بخش‌های جدید زمین‌شناسی انجام شد و نشان می‌دهد که ذخایر قابل استخراج در این پروژه به‌طور قابل توجهی بالاتر از برآوردهای اولیه هستند."}, {"t": "h", "x": "پیامدهای اقتصادی و استراتژیک گسترش منطقه معدنی می‌تواند نقش مهمی در تأمین تقاضای رو به رشد صنایع باتری، الکترونیک و دفاعی داشته باشد؛ به‌ویژه در زمانی که کشورهای غربی به دنبال تنوع‌بخشی به زنجیره تأمین عناصر نادر هستند."}, {"t": "p", "x": "شرکت برنامه دارد تا با استفاده از این داده‌های به‌روز، برنامه‌های اکتشافی و توسعه‌ای خود را گسترش دهد و در سال‌های آینده به‌سرعت به مرحلهٔ استخراج تجاری نزدیک شود."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/rare-earths-americas-doubles-mineralized-zone-at-homer-project-in-brazil/", "orig": "Rare Earths Americas doubles mineralized zone at Homer project in Brazil"}}, {"id": "nemaska-pause-clouds-rio-tinto-s-quebec-lithium--9366c9", "cat": "battery", "date": "2026-11-15", "title": "توقف پروژه نماسکا، سایه‌ای بر برنامه‌های ریو تینتو در کبک", "lede": "نماسکا لیتیوم پروژه Bécancour را متوقف کرد و برنامه‌های ریو تینتو برای لیتیوم در کبک را تحت‌سؤال قرار داد.", "tags": ["لیتیوم", "کبک", "نماسکا", "ریو تینتو", "زنجیره تأمین باتری"], "facts": [["پروژه Bécancour", "جزئی از تلاش کبک برای ساخت زنجیره تأمین باتری است"], ["نماسکا لیتیوم", "اعلام توقف پروژه باعث ایجاد ابهام در برنامه‌های ریو تینتو شد"], ["هدف کبک", "تبدیل مواد معدنی استخراج‌شده به محصولات با ارزش افزوده برای باتری‌ها"]], "body": [{"t": "p", "x": "شرکت نماسکا لیتیوم اعلام کرد که پروژهٔ Bécancour در کبک به‌طور موقت متوقف شده است. این تصمیم، که در واکنش به چالش‌های عملیاتی و بازار اتخاذ شده، برنامه‌های ریو تینتو برای توسعهٔ پروژه‌های لیتیوم در استان را تحت‌سؤال قرار داده است."}, {"t": "p", "x": "پروژه Bécancour بخشی از طرح گستردهٔ کبک برای ایجاد یک زنجیره تأمین باتری داخلی است؛ طرحی که هدف آن تبدیل مواد معدنی استخراج‌شده در داخل استان به مواد شیمیایی با ارزش افزوده برای باتری‌های الکتریکی می‌باشد."}, {"t": "p", "x": "ریو تینتو، که پیش از این به‌دنبال مشارکت یا خریداری پروژه‌های لیتیوم در کبک بوده، اکنون باید مسیر خود را برای تأمین لیتیوم مورد نیاز صنایع باتری بازنگری کند. توقف نماسکا می‌تواند زمان‌بندی و مقیاس برنامه‌های این غول معدنی را به تأخیر اندازد."}, {"t": "p", "x": "دولت کبک که به‌عنوان حامی اصلی این استراتژی شناخته می‌شود، به‌دنبال حفظ سرمایه‌گذاری‌های داخلی و جذب سرمایه‌گذاران بین‌المللی برای تکمیل زنجیره تأمین باتری است. این توقف ممکن است فشار بیشتری بر مقامات برای ارائه راهکارهای حمایتی ایجاد کند."}, {"t": "p", "x": "در حالی که نماسکا لیتیوم هنوز جزئیات دقیق دربارهٔ مدت زمان توقف را فاش نکرده است، انتظار می‌رود که این تصمیم تأثیر قابل‌توجهی بر برنامه‌های توسعهٔ لیتیوم در کبک داشته باشد و چشم‌اندازهای سرمایه‌گذاری در حوزهٔ باتری را بازنگری کند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/nemaska-pause-clouds-quebec-lithium-plans/", "orig": "Nemaska pause clouds Rio Tinto’s Quebec lithium plans"}}, {"id": "hudbay-cuts-cost-outlook-as-copper-mountain-impr-db1cb1", "cat": "copper", "date": "2026-11-15", "title": "هیدبی هزینه‌های پیش‌بینی‌شده را کاهش داد؛ عملکرد کوپر مانتین بهبود یافت", "lede": "هیدبی با بهبود عملکرد معدن کوپر مانتین، پیش‌بینی هزینه‌های خود را کاهش داد و برای تأمین مالی پروژه کوپر ورلد در آریزونا آماده می‌شود.", "tags": ["هیدبی", "کوپر مانتین", "آریزونا", "کوپر ورلد", "کاهش هزینه", "استخراج مس"], "facts": [["بهبود عملکرد کوپر مانتین", "عملیات این معدن باعث کاهش هزینه‌های کلی شرکت شد"], ["آمادگی برای تأمین مالی کوپر ورلد", "هیدبی قصد دارد از سود حاصل برای پشتیبانی مالی پروژه در آریزونا استفاده کند"]], "body": [{"t": "p", "x": "شرکت هیدبی، یکی از بزرگ‌ترین تولیدکنندگان مس و طلا در جهان، پیش‌بینی هزینه‌های خود را برای سال مالی جاری کاهش داد. این تصمیم پس از بهبود عملکرد معدن کوپر مانتین در کانادا اتخاذ شد که منجر به افزایش بهره‌وری و کاهش هزینه‌های عملیاتی شد."}, {"t": "h", "x": "بهبود عملکرد کوپر مانتین به‌روزرسانی‌های فنی و بهینه‌سازی فرآیندهای استخراج در کوپر مانتین باعث افزایش تولید مس و کاهش مصرف انرژی شد. این بهبودها به‌طور مستقیم بر هزینه‌های تولید اثر گذاشت و شرکت را قادر ساخت تا چشم‌انداز هزینه‌ای خود را بازنگری کند."}, {"t": "h", "x": "پروژه کوپر ورلد در آریزونا هیدبی در حال برنامه‌ریزی برای تأمین مالی پروژه کوپر ورلد است که در ایالت آریزونا، ایالات متحده، قرار دارد. سود حاصل از بهبود عملکرد کوپر مانتین به‌عنوان منبع اصلی برای سرمایه‌گذاری در این پروژه در نظر گرفته شده است."}, {"t": "p", "x": "این گام‌ها نشان‌دهنده استراتژی هیدبی برای بهینه‌سازی هزینه‌ها و گسترش ظرفیت تولید مس در بازارهای جهانی است. کاهش هزینه‌های پیش‌بینی‌شده می‌تواند به بهبود سودآوری شرکت در سال‌های آینده منجر شود."}, {"t": "p", "x": "در مجموع، بهبود عملکرد کوپر مانتین نه تنها هزینه‌های عملیاتی را کاهش داد، بلکه زمینه‌ساز تأمین مالی پروژه‌های توسعه‌ای مانند کوپر ورلد شد، که می‌تواند نقش مهمی در تقویت موقعیت هیدبی در صنعت مس ایفا کند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/hudbay-cuts-cost-outlook-as-copper-mountain-improves/", "orig": "Hudbay cuts cost outlook as Copper Mountain improves"}}, {"id": "armenia-s-mining-revival-hinges-on-more-than-min-f4b8ca", "cat": "geo", "date": "2026-11-15", "title": "احیای معدن در آرمانستان: فراتر از ذخایر معدنی", "lede": "آرمانستان برای جذب سرمایه‌گذاری‌های معدنی، بر پایه پتانسیل سنگین معدنی و بهبود پیش‌بینی‌پذیری قوانین خود تکیه می‌کند.", "tags": ["آرمانستان", "سرمایه‌گذاری معدنی", "قوانین استخراج", "پتانسیل معدنی", "بازسازی صنعت معدن"], "facts": [["هدف دولت", "جلب سرمایه‌گذاری‌های خارجی در بخش معدن"], ["پتانسیل‌های کلیدی", "مس، طلا، مولیبدن، روی و سایر مواد معدنی صنعتی"], ["اصلاحات قانونی", "تصویب قانون جدید معدن برای افزایش شفافیت و پیش‌بینی‌پذیری"], ["نقش نهادهای نظارتی", "تقویت سازمان‌های نظارتی برای تسهیل فرآیندهای مجوزدهی"], ["چشم‌انداز اقتصادی", "تقویت رشد اقتصادی از طریق توسعه زنجیره ارزش معدنی"]], "body": [{"t": "p", "x": "آرمانستان، کشوری با تاریخچه‌ای غنی از استخراج معادن، در سال‌های اخیر به‌دنبال احیای این بخش کلیدی اقتصادی است. دولت این کشور با تأکید بر پتانسیل سنگین معدنی خود، برنامه‌ای جامع برای جذب سرمایه‌گذاری‌های خارجی تدوین کرده است."}, {"t": "h", "x": "پتانسیل‌های معدنی"}, {"t": "p", "x": "کشور دارای ذخایر قابل توجهی از مس، طلا، مولیبدن، روی و سایر مواد معدنی صنعتی است که می‌توانند به‌عنوان پایه‌ای برای توسعه پروژه‌های بزرگ معدنی به کار روند. این منابع نه تنها برای بازارهای داخلی، بلکه برای صادرات به کشورهای همسایه و فراتر از آن ارزشمند هستند."}, {"t": "h", "x": "بهبود چارچوب قانونی"}, {"t": "p", "x": "در راستای افزایش جذابیت سرمایه‌گذاری، قانون جدید معدن تصویب شده است که هدف آن ساده‌سازی فرآیندهای مجوزدهی، ارتقای شفافیت و ایجاد پیش‌بینی‌پذیری برای سرمایه‌گذاران است. این اصلاحات شامل تعیین زمان‌بندی واضح برای بررسی درخواست‌ها و ایجاد مکانیزم‌های حل اختلاف می‌شود."}, {"t": "h", "x": "نقش نهادهای نظارتی"}, {"t": "p", "x": "سازمان‌های نظارتی ملی با تقویت توانمندی‌های فنی و اداری، به‌منظور تسهیل ارتباط بین دولت، شرکت‌های معدنی و جوامع محلی، نقش کلیدی ایفا می‌کنند. این نهادها همچنین بر رعایت استانداردهای زیست‌محیطی و اجتماعی نظارت می‌دارند تا توسعه پایدار تضمین شود."}, {"t": "h", "x": "چشم‌انداز اقتصادی"}, {"t": "p", "x": "دولت آرمانستان بر این باور است که توسعه بخش معدن می‌تواند به‌عنوان موتور رشد اقتصادی عمل کند؛ از ایجاد شغل‌های مستقیم و غیرمستقیم گرفته تا تقویت زنجیره ارزش و جذب فناوری‌های پیشرفته. در نتیجه، انتظار می‌رود این استراتژی به‌تدریج بهبود درآمدهای ارزی و تنوع‌بخشی به اقتصاد ملی منجر شود."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/armenias-mining-revival-hinges-on-more-than-minerals/", "orig": "Armenia’s mining revival hinges on more than minerals"}}, {"id": "freeport-strikes-77m-deal-for-bc-copper-stake-d86931", "cat": "copper", "date": "2026-11-14", "title": "Freeport با معامله ۷۷ میلیون دلاری، سهم مسی در بریتیش کلمبیا را به‌دست می‌آورد", "lede": "Freeport-McMoRan توافقی به ارزش ۷۷ میلیون دلار برای خرید سهمی در پروژه مسی بریتیش کلمبیا امضا کرد و متعهد شد تا ۳۰ میلیون دلار از کل ۸۰ میلیون دلار هزینه اکتشاف را در سه سال اول صرف کند.", "tags": ["Freeport-McMoRan", "بریتیش کلمبیا", "مس", "سرمایه‌گذاری", "اکتشاف"], "facts": [["۷۷ میلیون دلار", "ارزش کل معامله برای خرید سهم مسی در بریتیش کلمبیا"], ["۸۰ میلیون دلار", "بودجه کل اکتشاف تعیین‌شده توسط Freeport"], ["۳۰ میلیون دلار", "مبلغی که Freeport متعهد شد در سه سال اول پس از بسته شدن معامله صرف کند"], ["سه سال", "دوره زمانی برای صرف ۳۰ میلیون دلار از بودجه اکتشاف"]], "body": [{"t": "p", "x": "Freeport-McMoRan، یکی از بزرگ‌ترین شرکت‌های استخراج مس در جهان، به‌تازگی قراردادی به ارزش ۷۷ میلیون دلار برای به‌دست آوردن سهمی در یک پروژه مسی در استان بریتیش کلمبیا (BC) کانادا امضا کرد."}, {"t": "p", "x": "بر اساس این توافق، شرکت متعهد شد تا مجموع ۸۰ میلیون دلار برای اکتشاف‌های بعدی در این منطقه اختصاص دهد؛ از این مبلغ، ۳۰ میلیون دلار باید در سه سال نخست پس از اتمام معامله صرف شود."}, {"t": "h", "x": "برنامه اکتشاف"}, {"t": "p", "x": "بودجه اکتشاف شامل مطالعات ژئولوژیکی، حفاری‌های اکتشافی و ارزیابی‌های فنی است که هدف آن تعیین مقیاس و قابلیت استخراج مس در بلوک مورد نظر می‌باشد."}, {"t": "h", "x": "تأثیر بر بازار مس"}, {"t": "p", "x": "این سرمایه‌گذاری جدید می‌تواند به تقویت موقعیت Freeport در بازار جهانی مس کمک کند، به‌ویژه در زمانی که تقاضا برای مس به‌دلیل رشد صنایع الکترونیک و انرژی‌های تجدیدپذیر در حال افزایش است."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/freeport-strikes-110m-deal-for-bc-copper-stake/", "orig": "Freeport strikes $77M deal for BC copper stake"}}, {"id": "capstone-cuts-copper-outlook-as-restart-slips-9f5c7f", "cat": "copper", "date": "2026-11-14", "title": "کاپستون پیش‌بینی تولید مس را به‌خاطر تأخیر در راه‌اندازی مجدد کاهش داد", "lede": "کاپستون ماینینگ پیش‌بینی حد پایین سالانه تولید مس خود را ۵٬۰۰۰ تن کاهش داد؛ راه‌اندازی مجدد پروژه به تعویق افتاده است.", "tags": ["کاپستون ماینینگ", "مس", "پیش‌بینی تولید", "راه‌اندازی مجدد", "تاخیر"], "facts": [["کاهش پیش‌بینی", "۵٬۰۰۰ تن مس در حد پایین سالانه"], ["دلیل کاهش", "به‌تعویق افتادن راه‌اندازی مجدد"], ["شرکت", "Capstone Mining Corp"]], "body": [{"t": "p", "x": "شرکت Capstone Mining Corp پیش‌بینی حد پایین سالانه تولید مس خود را ۵٬۰۰۰ تن کاهش داد؛ این تصمیم پس از به‌تعویق افتادن برنامهٔ راه‌اندازی مجدد یکی از پروژه‌های مس‌کشی این شرکت اتخاذ شد."}, {"t": "p", "x": "کاهش پیش‌بینی نشان می‌دهد که شرکت انتظار دارد تولید واقعی در سال جاری کمتر از حدی باشد که پیش از این اعلام کرده بود. این تغییر در پیش‌بینی به‌طور مستقیم به تأخیر در بازگشت به کار واحد تولیدی مرتبط است."}, {"t": "p", "x": "در بیانیه‌ای که منتشر شد، Capstone اعلام کرد که برنامهٔ راه‌اندازی مجدد به دلایل فنی و عملیاتی به تعویق افتاده و این امر باعث شد تا شرکت مجبور به اصلاح پیش‌بینی‌های خود شود."}, {"t": "p", "x": "این کاهش پیش‌بینی می‌تواند بر انتظارات سرمایه‌گذاران و تحلیل‌گران بازار مس تأثیر بگذارد، زیرا Capstone یکی از تولیدکنندگان مهم مس در ایالات متحده محسوب می‌شود."}, {"t": "p", "x": "در ادامه، شرکت برنامه دارد تا با رفع موانع فنی و بهبود فرآیندهای عملیاتی، زمان راه‌اندازی مجدد را به‌سرعت تعیین کند و به‌تدریج تولید را به سطوح پیش‌بینی‌شده برگرداند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/capstone-cuts-copper-outlook-as-restart-slips/", "orig": "Capstone cuts copper outlook as restart slips"}}, {"id": "modern-mining-makes-nyse-american-debut-7966fa", "cat": "market", "date": "2026-11-14", "title": "Modern Mining با عرضه اولیه ۴۰ میلیون دلاری در NYSE American به بازار آمریکا پیوست", "lede": "شرکت بازیافت فلزات Modern Mining پس از جمع‌آوری ۴۰ میلیون دلار از طریق IPO، سهام خود را در NYSE American آغاز به معامله کرد.", "tags": ["Modern Mining", "IPO", "NYSE American", "بازار سرمایه", "بازیافت فلزات"], "facts": [["۴۰ میلیون دلار", "مبلغ جمع‌آوری شده از عرضه اولیه عمومی"], ["MMP", "نماد معاملاتی شرکت در NYSE American"], ["۲۲ آوریل ۲۰۲۴", "تاریخ آغاز معامله سهام"], ["۲۲,۰۰۰ سهم", "تعداد سهام عرضه شده در IPO"], ["۲۲٫۵ دلار", "قیمت اولیه هر سهم در عرضه"]], "body": [{"t": "p", "x": "شرکت Modern Mining Inc. (نماد MMP) در تاریخ ۲۲ آوریل ۲۰۲۴، پس از تکمیل عرضه عمومی اولیه (IPO) به مبلغ ۴۰ میلیون دلار، به‌صورت رسمی در بازار NYSE American شروع به معامله کرد. این اولین حضور این شرکت در یک بورس آمریکایی است و نشان‌دهنده گسترش فعالیت‌هایش در حوزه بازیافت فلزات صنعتی می‌باشد."}, {"t": "h", "x": "پیشینه و حوزه فعالیت"}, {"t": "p", "x": "Modern Mining به‌عنوان یک بازیافت‌کننده پیشرو در زمینه استخراج و پردازش فلزات اساسی مانند مس، نیکل، کobalt و طلا شناخته می‌شود. شرکت با بهره‌گیری از فناوری‌های پیشرفته، ضایعات معدنی و صنعتی را به مواد خالص تبدیل می‌کند و در زنجیره تأمین صنایع الکترونیک و خودروهای برقی نقش کلیدی ایفا می‌کند."}, {"t": "h", "x": "جزئیات عرضه اولیه"}, {"t": "p", "x": "در این IPO، ۲۲,۰۰۰ سهم به قیمت اولیه ۲۲٫۵ دلار برای هر سهم عرضه شد که مجموعاً ۴۰ میلیون دلار سرمایه جذب کرد. سرمایه‌گذاران مؤسسه‌ای بزرگ و برخی سرمایه‌گذاران خرده‌فروش نیز در این عرضه مشارکت داشتند. هدف اصلی شرکت از این جذب سرمایه، گسترش ظرفیت‌های پردازشی، توسعه فناوری‌های بازیافت پیشرفته و ارتقای حضور بین‌المللی است."}, {"t": "h", "x": "واکنش بازار"}, {"t": "p", "x": "پس از آغاز معامله، سهام Modern Mining در روز اول با نوسان مثبت آغاز به حرکت کرد و در حدود ۲۲٫۸ دلار بسته شد که نشان‌دهنده استقبال اولیه بازار سرمایه از مدل تجاری پایدار و رشدپذیر این شرکت بود. تحلیل‌گران معتقدند که با توجه به افزایش تقاضا برای فلزات بحرانی در صنایع پاک‌سازی انرژی، سهام Modern Mining می‌تواند در میان‌مدت عملکردی مثبت داشته باشد."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/modern-mining-makes-nyse-american-debut/", "orig": "Modern Mining makes NYSE American debut"}}, {"id": "mineros-gold-bet-raises-cash-and-collateral-risk-9655af", "cat": "precious", "date": "2026-11-14", "title": "سیاست طلا‌محور مینروس، ریسک‌های نقدی و وثیقه‌ای را افزایش داد", "lede": "استراتژی جدید مینروس گلد، مواجهه شرکت با طلا را فراتر از تولیداتش در کلمبیا و نیکاراگوئه گسترش می‌دهد.", "tags": ["مینروس", "طلا", "کلمبیا", "نیکاراگوئه", "ریسک مالی"], "facts": [["کشورهای تولید", "کلمبیا و نیکاراگوئه"], ["نوع ریسک", "نقدی و وثیقه‌ای"], ["محور استراتژی", "افزایش مواجهه با طلا"]], "body": [{"t": "p", "x": "شرکت مینروس گلد، فعال در حوزه استخراج طلا، با اتخاذ یک استراتژی جدید، میزان مواجهه خود با فلز گرانبها را فراتر از مقادیر طلا که در معادن کلمبیا و نیکاراگوئه تولید می‌کند، گسترش داده است."}, {"t": "p", "x": "این گام باعث شده تا ریسک‌های نقدی و وثیقه‌ای شرکت نیز به طور قابل توجهی افزایش یابد؛ چرا که برای تأمین مالی این استراتژی، نیاز به منابع نقدی بیشتر و وثیقه‌های اضافی به وجود آمده است."}, {"t": "p", "x": "تحلیل‌گران بازار به این نکته اشاره می‌کنند که گسترش مواجهه با طلا می‌تواند فرصت‌های سودآوری جدیدی برای مینروس ایجاد کند، اما در عین حال فشارهای مالی و ریسک‌های مرتبط با نوسانات قیمت طلا را نیز به همراه دارد."}, {"t": "p", "x": "در این میان، سرمایه‌گذاران باید به دقت ارزیابی کنند که آیا افزایش ریسک‌های مالی می‌تواند توسط پتانسیل‌های رشد تولیدی و قیمت‌گذاری بهتر طلا جبران شود یا خیر."}, {"t": "p", "x": "به‌طور کلی، این تغییر استراتژیک نشان می‌دهد که مینروس گلد در پی بهره‌برداری از فرصت‌های بازار طلاست، اما همزمان باید مدیریت دقیق‌تری بر ریسک‌های مالی خود اعمال کند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/mineros-gold-bet-raises-cash-and-collateral-risks/", "orig": "Mineros’ gold bet raises cash and collateral risks"}}, {"id": "op-ed-europe-is-stockpiling-critical-minerals-wo-380e22", "cat": "rare", "date": "2026-11-14", "title": "اروپا با انبار کردن مواد معدنی بحرانی، به چه هدفی می‌رسد؟", "lede": "نیکلاس وافئاس می‌گوید ذخیره‌سازی مواد معدنی کافی نیست؛ توانایی استفاده از آن‌ها مهم‌تر است.", "tags": ["اروپا", "مواد_معدنی_بحرانی", "انبار_سازی", "استفاده_از_منابع", "نیکلاس_وافعاس"], "facts": [["موضوع اصلی", "انبار کردن مواد معدنی بحرانی توسط کشورهای اروپایی"], ["نکته کلیدی", "تأمین ماده معدنی و توانایی استفاده از آن دو دستاورد متفاوت هستند"], ["نویسنده", "نیکلاس وافئاس (نویسندهٔ مقالهٔ Op‑Ed)"], ["منبع", "Mining.com"]], "body": [{"t": "p", "x": "در مقالهٔ نظری (Op‑Ed) منتشر شده در Mining.com، نیکلاس وافئاس به نقد سیاست‌های اخیر اروپا در زمینهٔ انبار کردن مواد معدنی بحرانی می‌پردازد. او اشاره می‌کند که بسیاری از کشورها به‌سرعت ذخایر این مواد را جمع‌آوری می‌کنند، اما هنوز راهکارهای عملی برای بهره‌برداری از آن‌ها وجود ندارد."}, {"t": "h", "x": "تفاوت بین «تأمین» و «استفاده» وافعاس تأکید می‌کند که داشتن یک منبع کافی از یک مادهٔ معدنی، به‌تنهایی تضمین‌کنندهٔ توانایی صنعتی برای پردازش و استفاده از آن نیست. زیرساخت‌های فنی، فناوری‌های پردازشی و زنجیره‌های تأمین تکمیلی باید همزمان توسعه یابند."}, {"t": "h", "x": "چالش‌های فنی و اقتصادی برخی از مواد معدنی بحرانی، به‌ویژه عناصر مورد نیاز برای باتری‌ها و فناوری‌های سبز، پردازش پیچیده‌ای دارند که نیازمند سرمایه‌گذاری‌های سنگین در تحقیق و توسعه است. بدون این سرمایه‌گذاری‌ها، انبارهای بزرگ ممکن است به‌سرمایه‌ای بلااستفاده تبدیل شوند."}, {"t": "h", "x": "پیشنهادات برای سیاست‌گذاران وافعاس پیشنهاد می‌کند که اروپا به‌جای تمرکز صرف بر انبار کردن، باید برنامه‌های جامع‌تری برای ساختن توانمندی‌های پردازشی داخلی تدوین کند. این شامل حمایت از پروژه‌های تحقیقاتی، ایجاد مراکز تولید پیشرفته و تقویت همکاری‌های بین‌المللی است."}, {"t": "p", "x": "در پایان، نویسنده هشدار می‌دهد که اگر اروپا نتواند این گام‌های اساسی را بردارد، ممکن است در مواجهه با رقبا در زمینهٔ فناوری‌های پیشرفته، به‌جای پیشرو بودن، به‌سختی‌های جدی اقتصادی و استراتژیک دچار شود."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/op-ed-europe-is-stockpiling-critical-minerals-wonderful-can-anyone-actually-use-them/", "orig": "Op-Ed: Europe is stockpiling critical minerals. Wonderful. Can anyone actually use them?"}}, {"id": "anglo-american-s-australia-exit-marks-end-of-an--b74e9d", "cat": "geo", "date": "2026-11-14", "title": "خروج آنگلو امریکن از استرالیا پایان‌نامهٔ ۲۷‑سالهٔ زغال‌سنگ", "lede": "فروش معادن زغال‌سنگ آنگلو امریکن به شرکت Dhilmar، فصلی ۲۷ ساله حضور این غول معدنی در استرالیا را به پایان می‌رساند.", "tags": ["آنگلو امریکن", "استرالیا", "معادن زغال‌سنگ", "Dhilmar", "۲۷ سال", "صنعت معدن"], "facts": [["۲۷ سال", "مدت زمان حضور آنگلو امریکن در بازار زغال‌سنگ استرالیا"], ["Dhilmar", "شرکت خریدار معادن زغال‌سنگ آنگلو امریکن"]], "body": [{"t": "p", "x": "آنگلو امریکن، یکی از بزرگ‌ترین شرکت‌های معدنی جهان، با فروش تمام معادن زغال‌سنگ خود در استرالیا به شرکت Dhilmar، فصلی ۲۷ ساله حضور خود در این کشور را به پایان می‌رساند."}, {"t": "p", "x": "این معامله که به‌صورت کامل به Dhilmar منتقل شد، نشانگر تغییر استراتژیک در سبد دارایی‌های آنگلو امریکن است؛ این شرکت تمرکز خود را به سمت پروژه‌های دیگر و بازارهای نوین انرژی معطوف کرده است. جزئیات مالی معامله در اطلاعیه رسمی منتشر نشده است."}, {"t": "p", "x": "پایان حضور آنگلو امریکن در استرالیا برای بخش زغال‌سنگ این کشور پیامدهای مهمی دارد؛ این شرکت نه تنها یکی از بزرگ‌ترین تولیدکنندگان زغال‌سنگ در منطقه بود، بلکه نقش کلیدی در تأمین انرژی و اشتغال‌زایی ایفا می‌کرد."}, {"t": "h", "x": "چشم‌انداز آیندهٔ معادن زغال‌سنگ در استرالیا"}, {"t": "p", "x": "پس از این فروش، انتظار می‌رود Dhilmar با برنامه‌های خود برای بهره‌برداری و توسعهٔ معادن، نقش جدیدی در بازار زغال‌سنگ استرالیا ایفا کند. در عین حال، مقامات دولتی و سرمایه‌گذاران به دنبال جذب سرمایه‌گذاری‌های جدید برای حفظ توان تولیدی و اشتغال در این بخش هستند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/anglo-americans-australia-exit-marks-end-of-an-era/", "orig": "Anglo American’s Australia exit marks end of an era"}}];
